sources.app.tsx:
// Paddle duel: a paddle-and-ball game for two people at a touch frame on a
// table, or one against the computer, in the 8-bit palette mode. Each
// player drags their own paddle in their half (every finger is followed on
// its own, so both play at once); the ball comes off a paddle at an angle
// from where it hit and gets faster with every return. First to the
// match's points wins. Twists: posts in the middle, two balls.
//
// Keys: W / S (or A / D) for the left or top paddle, the arrows for the
// other, Space or Enter to start, P or Escape to pause; against the computer
// any of them moves yours. GPIO buttons by the "Buttons" setting.
import { box, clip, target, textCenter, textWidth, title } from './gfx'
import {
  A, B, DOWN, LEFT, RIGHT, START, TAP, UP, drags, handle, held as heldNow, lastTapX, lastTapY, press, ptrX, ptrY,
  releaseAll, setButtons, setHitTest, take,
} from './input'
import {
  UI_BLINK, UI_BORDER, UI_DIALOG, UI_DIM, UI_FACE, UI_ICON, UI_SHADOW, UI_TEXT, UI_TITLE, blink, cardCell, cellSize, choice,
  clockReset, dialog, drawPause, drawSlowCard, fastScreen, fitScale, highContrast, pauseChoice, stepsDue, uiColors, reseed,
} from './ui'
import {
  FIELD, PAUSE, centrePaddles, draw, drawField, flashing, lengthV, newMatch, resume, score, setField, setMatchTo,
  roundField, sideways, snapshot, tick, toU, toV, winnerOf,
} from './game'

const STEP_MS = 1000 / 60
const IDLE_MS = 30000

// The table: the field, its lines, each player's paddle, shade and score,
// the ball, its glow and trail, posts, sparks and the pause icon.
const COLORS = [0x0d2622, 0x2f5e54, 0x5a8a7e, 0xff8a3a, 0xa8481a, 0x6a3a22, 0x3ac8ff, 0x1a6a9a, 0x1f5470,
  0xffffff, 0xfff6c0, 0x7aa89a, 0x3e6a60, 0x1f4a42, 0x9ad8c8, 0xfff0a0, 0x9ad8c8]
const INK = '01111111111001111'
const THEME = {
  title: [0xfff6c0, 0xffd27a, 0xff9a4a, 0xff6a3a, 0xd83a3a], shadow: 0x061412, panel: 0x0a1c18, edge: 0x2f5e54,
  border: 0x5a8a7e, face: 0x163a33, lit: 0x3ac8ff, icon: 0xe8fff8, iconLit: 0x06201a, text: 0xe8fff8,
  dim: 0x8ab8aa, dialog: 0x0a1c18, dialogEdge: 0x9ad8c8, accent: 0x3ac8ff, good: 0xffe14a,
}

let cells: Uint8Array | null = null
let bg: Uint8Array = new Uint8Array(1)
let cols = 0
let rows = 0
let px = 4
let width = 0
let height = 0
const pal = new Uint32Array(256)
const opts = { width: 1, height: 1, pixelSize: 1 }
// Where the cards and dialogs go: the whole grid, or on a round panel
// (context.round) the field inside the circle.
let round = false
let AX = 0
let AY = 0
let AW = 0
let AH = 0
// The title card's room on a round panel: taller than the field, inside the circle.
let titleRoom: number[] | null = null

type Mode = 'title' | 'play' | 'pause' | 'over' | 'slow'
let mode: Mode = 'title'
let idleFrom = 0
let overAt = 0
let overReady = false
let snapAt = 0
let steps = 0
let vsComputer = true
let asked = 0 // a key that picked the players: 1 or 2

let settingsAt = 0
let layoutKey = ''
let hc = false
let fast = true
let difficulty = 1
let points = 7
let twist = 'none'
let faster = 1.05
let defaultMode = 'computer'
let record: any = {}

// The title's two buttons: x, y, w, h each (1 player, 2 players).
const pick = new Int16Array(8)

// W / S or A / D: the first paddle (left, top); the arrows: the second.
function keys(code: string): number {
  switch (code) {
    case 'KeyW': case 'KeyA': return LEFT
    case 'KeyS': case 'KeyD': return RIGHT
    case 'ArrowUp': case 'ArrowLeft': return UP
    case 'ArrowDown': case 'ArrowRight': return DOWN
    case 'Space': case 'Enter': case 'NumpadEnter': case 'KeyZ': return A
    case 'KeyP': case 'Escape': return START
    case 'Digit1': case 'Numpad1': asked = 1; return A
    case 'Digit2': case 'Numpad2': asked = 2; return A
  }
  return 0
}

export function get(app, context) {
  const now = Date.now()
  const w = context.imageWidth || app.frame.width
  const h = context.imageHeight || app.frame.height
  round = context.round === true
  if (!cells || w !== width || h !== height || now - settingsAt > 1000) settings(app, w, h, now)
  if (mode === 'slow') {
    frameos.setNextSleep(3600)
    return frameos.pixels(cells!, pal, opts)
  }
  let pressed = take()
  const held = heldNow()
  if (mode === 'title') {
    let players = 0
    if (pressed & TAP) players = hitPick(lastTapX() / px, lastTapY() / px)
    if (!players && pressed & (A | START)) players = asked || (defaultMode === 'two' ? 2 : 1)
    asked = 0
    if (players) {
      start(now, players === 1)
      pressed = 0
    }
  } else if (mode === 'pause' || (mode === 'over' && overReady)) {
    let choice = 0
    if (pressed & TAP) choice = pauseChoice(lastTapX() / px, lastTapY() / px)
    if (choice === 1 || pressed & (A | START)) {
      if (mode === 'pause') unpause(now)
      else start(now, vsComputer)
    } else if (choice === 2 || pressed & B) menu(now)
    pressed = 0
  } else if (mode === 'over' && now - overAt > 1500) {
    overReady = true
    overDialog()
  }
  if (mode === 'play') {
    if (pressed & START) pause()
    else play(now, held)
  }
  colors(now)
  if (mode === 'pause' || ((mode === 'title' || mode === 'over') && now - idleFrom > IDLE_MS)) frameos.setNextSleep(3600)
  return frameos.pixels(cells!, pal, opts)
}

export function onEvent(app, context) {
  const event = context.event
  if (event === 'close') {
    // Every finger lets go, and a game going on pauses.
    releaseAll()
    if (mode === 'play') press(START)
    return false
  }
  if (event === 'open') return mode !== 'slow'
  if (event === 'back') press(START)
  else if (event === 'forward') press(mode === 'play' ? 0 : A)
  else if (handle(event, context.payload || {}, keys) < 0) return false
  idleFrom = Date.now()
  return mode !== 'play' && mode !== 'slow'
}

// --- settings and the layout -------------------------------------------------------------

function settings(app: any, w: number, h: number, now: number) {
  settingsAt = now
  const st = app.state
  const frame = app.frame
  const fresh = !cells
  if (fresh) record = readRecord(st.record)
  hc = highContrast(st.contrast, frame)
  fast = fastScreen(frame)
  difficulty = ['easy', 'normal', 'hard'].indexOf(choice(st.difficulty, ['normal', 'easy', 'hard']))
  points = Number(choice(st.points, ['7', '5', '11', '15']))
  setMatchTo(points)
  twist = choice(st.twist, ['none', 'blocks', 'balls', 'both'])
  faster = [1.03, 1.05, 1.08][['gentle', 'normal', 'fast'].indexOf(choice(st.speedUp, ['normal', 'gentle', 'fast']))]
  defaultMode = choice(st.mode, ['computer', 'two'])
  setButtons(st.buttons)
  for (let i = 0; i < COLORS.length; i++) pal[i] = hc ? (INK[i] === '1' ? 0xffffff : 0) : COLORS[i]
  uiColors(pal, THEME, hc)
  const sides = choice(st.sides, ['auto', 'across', 'updown'])
  const across = sides === 'across' || (sides === 'auto' && h <= w * 1.1)
  const size = cellSize(st.pixelSize, w, h, 110)
  const key = [w, h, size, across, fast, twist, round].join(':')
  if (key === layoutKey && !fresh) return
  layoutKey = key
  width = w
  height = h
  px = fast ? size : cardCell(size, w)
  cols = Math.max(40, Math.floor(w / px))
  rows = Math.max(40, Math.floor(h / px))
  cells = new Uint8Array(cols * rows)
  bg = new Uint8Array(cols * rows)
  opts.width = cols
  opts.height = rows
  opts.pixelSize = px
  target(cells, cols, rows)
  if (!fast) {
    mode = 'slow'
    drawSlowCard(cols, rows, 'PADDLE DUEL', ['A PADDLE GAME FOR TWO AT A', 'FAST TOUCH SCREEN: LCD OR HDMI.', '',
      'ON E-PAPER IT SLEEPS HERE.', '', recordLine()], null)
    return
  }
  const room = round ? roundField(cols, rows, px, across) : null
  AX = room ? room[0] : 0
  AY = room ? room[1] : 0
  AW = room ? room[2] : cols
  AH = room ? room[3] : rows
  setField(cells, bg, cols, rows, across, px, room)
  if (room) {
    const r = Math.min(cols, rows) / 2 - Math.ceil(12 / px)
    const th = Math.floor(r * 1.45)
    const tw = 2 * Math.floor(Math.sqrt(r * r - (th / 2) * (th / 2)))
    titleRoom = [Math.round((cols - tw) / 2), Math.round((rows - th) / 2), tw, th]
  } else titleRoom = null
  setHitTest((x, y) => {
    // The pause button on the middle line; anything else is a paddle's finger.
    if (mode !== 'play') return 0
    const u = toU(x, y, px)
    const v = toV(x, y, px)
    return u >= PAUSE[0] - 1 && u < PAUSE[0] + PAUSE[2] + 1 && v >= PAUSE[1] - 1 && v < PAUSE[1] + PAUSE[2] + 1 ? START : 0
  })
  if (fresh) {
    reseed(now)
    idleFrom = now
    const snap = frameos.recall('snap') as any
    if (snap && snap.mode) {
      vsComputer = snap.mode === 'computer'
      resume(snap, twist, faster)
      mode = 'pause'
    } else mode = 'title'
  } else if (mode === 'play' || mode === 'pause') {
    const snap = snapshot()
    resume(snap, twist, faster)
    mode = 'pause'
  } else if (mode === 'slow' || mode === 'over') mode = 'title'
  if (mode === 'title') titleScreen()
  else {
    draw(0)
    pauseDialog()
  }
}

function readRecord(raw: any): any {
  let r = raw
  if (typeof r === 'string') {
    try {
      r = JSON.parse(r)
    } catch (e) {
      r = null
    }
  }
  return r && typeof r === 'object' ? r : {}
}

function recordLine(): string {
  const key = ['easy', 'normal', 'hard'][difficulty]
  const r = record[key]
  if (!r || !(r[0] + r[1])) return ''
  return 'VS COMPUTER: ' + r[0] + ' WON ' + r[1] + ' LOST'
}

// --- the modes ----------------------------------------------------------------------------------

function start(now: number, computer: boolean) {
  vsComputer = computer
  mode = 'play'
  steps = 0
  centrePaddles()
  newMatch(twist, faster)
  clockReset(now)
}

function play(now: number, held: number) {
  // Fingers: each in its half moves that half's paddle; against the computer, any finger moves yours.
  let aim0 = -1
  let aim1 = -1
  const half = lengthV() / 2
  for (let id = 0; id < drags.length; id++) {
    if (!drags[id]) continue
    const u = toU(ptrX[id], ptrY[id], px)
    if (vsComputer || toV(ptrX[id], ptrY[id], px) >= half) aim1 = u
    else aim0 = u
  }
  const move0 = held & LEFT ? -1 : held & RIGHT ? 1 : 0
  let move1 = held & UP ? -1 : held & DOWN ? 1 : 0
  if (vsComputer && !move1) move1 = move0
  const n = stepsDue(now, STEP_MS, 4)
  for (let i = 0; i < n && winnerOf() < 0; i++) tick(vsComputer ? 0 : move0, move1, aim0, aim1, vsComputer ? difficulty : -1)
  steps++
  draw(steps)
  if (winnerOf() >= 0) {
    mode = 'over'
    overAt = now
    overReady = false
    idleFrom = now
    frameos.remember('snap', null)
    if (vsComputer) {
      const key = ['easy', 'normal', 'hard'][difficulty]
      const r = record[key] || [0, 0]
      if (winnerOf() === 1) r[0]++
      else r[1]++
      record[key] = r
      frameos.setState('record', record)
    }
    overDialog()
    return
  }
  if (now - snapAt > 1000) {
    snapAt = now
    const snap: any = snapshot()
    snap.mode = vsComputer ? 'computer' : 'two'
    frameos.remember('snap', snap)
  }
}

function pause() {
  mode = 'pause'
  releaseAll()
  const snap: any = snapshot()
  snap.mode = vsComputer ? 'computer' : 'two'
  frameos.remember('snap', snap)
  pauseDialog()
}

function unpause(now: number) {
  mode = 'play'
  cells!.set(bg)
  draw(steps)
  clockReset(now)
}

function menu(now: number) {
  mode = 'title'
  idleFrom = now
  frameos.remember('snap', null)
  titleScreen()
}

function pauseDialog() {
  clip(0, 0, cols, rows)
  drawPause(AX, AY, AW, AH, 'P: RESUME', 'PAUSED', score[0] + ' - ' + score[1])
}

function overDialog() {
  clip(0, 0, cols, rows)
  cells!.set(bg)
  const won = winnerOf()
  const across = sideways()
  const head = vsComputer ? (won === 1 ? 'YOU WIN!' : 'COMPUTER WINS') : across
    ? (won === 0 ? 'LEFT WINS!' : 'RIGHT WINS!') : (won === 0 ? 'TOP WINS!' : 'BOTTOM WINS!')
  const line = score[0] + ' - ' + score[1]
  if (overReady) drawPause(AX, AY, AW, AH, '', head, line, 'AGAIN', 'MENU')
  else {
    const s = fitScale(head.length, AW - 8, 4)
    title(head, AX + (AW >> 1), AY + (AH >> 1) - 3 * s, s, UI_TITLE, UI_SHADOW)
  }
}

/** The title: the table, and a card with the two ways to play. */
function titleScreen() {
  drawField()
  centrePaddles()
  draw(0)
  clip(0, 0, cols, rows)
  const rec = recordLine()
  const AX = titleRoom ? titleRoom[0] : 0
  const AY = titleRoom ? titleRoom[1] : 0
  const AW = titleRoom ? titleRoom[2] : cols
  const AH = titleRoom ? titleRoom[3] : rows
  // The biggest text that fits: the name at twice the size of the rest.
  let s = fitScale(20, AW - 8, 3)
  let big = 1
  for (; ; s--) {
    big = Math.max(1, Math.min(fitScale(7, AW - 10, 5), 2 * s))
    if (s === 1 || 13 * big + (41 + (rec ? 7 : 0)) * s + 8 <= AH - 4) break
  }
  const dw = Math.min(AW - 4, Math.max(textWidth('PADDLE', big) + 8 * s, 40 * s, textWidth(rec, s) + 6 * s,
    textWidth('TAP ONE TO PLAY', s) + 6 * s))
  const dh = Math.min(AH - 4, 13 * big + 41 * s + (rec ? 7 * s : 0) + 8)
  const dx = AX + ((AW - dw) >> 1)
  const dy = AY + ((AH - dh) >> 1)
  dialog(dx, dy, dw, dh)
  const cx = AX + (AW >> 1)
  title('PADDLE', cx, dy + 3, big, UI_TITLE, UI_SHADOW)
  title('DUEL', cx, dy + 3 + 6 * big, big, UI_TITLE, UI_SHADOW)
  let y = dy + 4 + 13 * big
  const bw = dw - 6 * s
  const bh = 11 * s
  for (let i = 0; i < 2; i++) {
    const label = i === 0 ? '1 PLAYER' : '2 PLAYERS'
    const first = (defaultMode === 'two') === (i === 1)
    box(dx + 3 * s, y, bw, bh, UI_FACE, first ? UI_TITLE + 2 : UI_BORDER, UI_DIALOG)
    textCenter(label, cx, y + 3 * s, s, UI_ICON)
    pick[i * 4] = dx + 3 * s
    pick[i * 4 + 1] = y
    pick[i * 4 + 2] = bw
    pick[i * 4 + 3] = bh
    y += bh + 3 * s
  }
  textCenter('FIRST TO ' + points, cx, y, s, UI_TEXT)
  y += 7 * s
  if (rec) {
    textCenter(rec, cx, y, s, UI_DIM)
    y += 7 * s
  }
  textCenter('TAP ONE TO PLAY', cx, dy + dh - 7 * s - 1, s, UI_BLINK)
}

function hitPick(x: number, y: number): number {
  for (let i = 0; i < 2; i++) {
    const at = i * 4
    if (x >= pick[at] && y >= pick[at + 1] && x < pick[at] + pick[at + 2] && y < pick[at + 1] + pick[at + 3]) return i + 1
  }
  return 0
}

function colors(now: number) {
  // A point lights the table in the scorer's color for a moment.
  const f = mode === 'play' ? flashing() : 0
  pal[FIELD] = hc ? 0 : f === 1 ? 0x3a2a1e : f === 2 ? 0x16344a : COLORS[FIELD]
  blink(pal, now, hc ? 0xffffff : THEME.text, hc ? 0 : THEME.dim)
}

sources.game.ts:
// Paddle duel's game. The rally is worked out along two axes, whatever way
// the screen is held: v from one player's end to the other's, u along the
// paddles. On a wide screen v runs left to right; on a tall one top to
// bottom, and the top player's numbers are drawn upside down for them.
// Player 0 is at v = 0 (left, or top), player 1 at the far end.
import { clip, fill, restore, target, text, textWidth } from './gfx'
import { UI_PANEL, rfloat, rint } from './ui'

export const FIELD = 0
export const LINE = 1
export const WALL = 2
export const P0 = 3 // a player's paddle, its shade, its score
export const P0_D = 4
export const P0_SCORE = 5
export const P1 = 6
export const P1_D = 7
export const P1_SCORE = 8
export const BALL = 9
export const BALL_GLOW = 10
export const GHOST = 11 // the ball's trail, two steps
export const GHOST2 = 12
export const BLOCK = 13
export const BLOCK_EDGE = 14
export const SPARK = 15
export const PAUSE_ICON = 16

let cells: Uint8Array = new Uint8Array(1)
let bg: Uint8Array = new Uint8Array(1)
let cols = 1
let rows = 1
let across = true // v runs across (paddles left and right)
let LU = 1 // the field along u and along v, in cells
let LV = 1
let PL = 8 // paddle length and thickness, and how far in from the end
let PT = 2
let PD = 4
let BS = 2 // the ball's size
// Where the field starts in the cells: 0, 0 but on a round panel, where it is
// a rectangle inside the circle and the scores sit in the arc above it.
let X0 = 0
let Y0 = 0
let round = false
/** The pause button: u, v, size. */
export const PAUSE = new Int16Array(3)

// --- the axes ------------------------------------------------------------------------------

function rect(u: number, v: number, du: number, dv: number, val: number) {
  if (across) fill(X0 + v, Y0 + u, dv, du, val)
  else fill(X0 + u, Y0 + v, du, dv, val)
}

function back(u: number, v: number, du: number, dv: number) {
  if (across) restore(bg, X0 + (v | 0), Y0 + (u | 0), (dv | 0) + 1, (du | 0) + 1)
  else restore(bg, X0 + (u | 0), Y0 + (v | 0), (du | 0) + 1, (dv | 0) + 1)
}

/** A pointer at scene pixels (x, y) in field cells: u and v. */
export function toU(x: number, y: number, px: number): number {
  return across ? y / px - Y0 : x / px - X0
}
export function toV(x: number, y: number, px: number): number {
  return across ? x / px - X0 : y / px - Y0
}

/** On a round panel: the field as a rectangle inside the circle, 4:3 along
 *  the way the ball goes (x, y, w, h in cells). */
export function roundField(gridCols: number, gridRows: number, px: number, sides: boolean): number[] {
  const r = Math.min(gridCols, gridRows) / 2 - Math.ceil(12 / px)
  const long = 2 * Math.floor(r * 0.8)
  const short = 2 * Math.floor(r * 0.6)
  const w = sides ? long : short
  const h = sides ? short : long
  return [Math.round((gridCols - w) / 2), Math.round((gridRows - h) / 2), w, h]
}
export function sideways(): boolean {
  return across
}
export function lengthV(): number {
  return LV
}

// --- the rally's state --------------------------------------------------------------------------

const NB = 2
const bOn = new Uint8Array(NB)
const bU = new Float32Array(NB)
const bV = new Float32Array(NB)
const bVU = new Float32Array(NB)
const bVV = new Float32Array(NB)
const bWait = new Int16Array(NB) // steps before a serve
// Where each ball was drawn the last three frames (a trail): u, v.
const trail = new Float32Array(NB * 6).fill(-99)

const padU = new Float32Array(2) // each paddle's top (u)
const padDrawn = new Float32Array(2).fill(-99)
export const score = new Int16Array(2)
let rally = 0
let speed0 = 1
let speed = 1
let speedUp = 1.05
let twoBalls = false
let blocks = false
let serveTo = 0
let winner = -1
let flash = 0
let flashBy = 0

// Blocks in the middle: u, v, du, dv each.
const NK = 3
const kU = new Float32Array(NK)
const kV = new Float32Array(NK)
const kDU = new Float32Array(NK)
const kDV = new Float32Array(NK)
let blockCount = 0

const NP = 24 // sparks
const pLife = new Uint8Array(NP)
const pU = new Float32Array(NP)
const pV = new Float32Array(NP)
const pVU = new Float32Array(NP)
const pVV = new Float32Array(NP)
const pAt = new Int32Array(NP).fill(-1)

export function setField(c: Uint8Array, layer: Uint8Array, gridCols: number, gridRows: number, sides: boolean, px: number,
    room: number[] | null = null) {
  cells = c
  bg = layer
  cols = gridCols
  rows = gridRows
  across = sides
  round = !!room
  X0 = room ? room[0] : 0
  Y0 = room ? room[1] : 0
  LU = room ? (across ? room[3] : room[2]) : across ? rows : cols
  LV = room ? (across ? room[2] : room[3]) : across ? cols : rows
  PL = Math.max(6, Math.round(LU * 0.2))
  PT = Math.max(2, Math.round(LV * 0.022))
  // The ends are no screen's edges inside a circle: no swipe to keep clear of.
  PD = room ? 3 : Math.max(3, Math.ceil(24 / px) + 1)
  BS = Math.max(2, Math.round(Math.min(LU, LV) * 0.028))
  const ps = Math.max(7, Math.ceil(48 / px))
  // Round: below the field (beside it when the ends are up and down), in the middle.
  PAUSE[0] = room ? (across ? LU + 2 : -2 - ps) : 2
  PAUSE[1] = ((LV - ps) / 2) | 0
  PAUSE[2] = ps
  target(cells, cols, rows)
  clip(0, 0, cols, rows)
  padU[0] = padU[1] = (LU - PL) / 2
}

/** A match: twists, how much faster each return makes the ball. */
export function newMatch(twist: string, faster: number) {
  score[0] = score[1] = 0
  winner = -1
  twoBalls = twist === 'balls' || twist === 'both'
  blocks = twist === 'blocks' || twist === 'both'
  speedUp = faster
  speed0 = LV / 130
  serveTo = rint(2)
  placeBlocks()
  drawField()
  serve()
}

function placeBlocks() {
  blockCount = 0
  if (!blocks) return
  // Three posts down the middle, leaving room to get past.
  const dv = Math.max(2, Math.round(LV * 0.03))
  const du = Math.max(3, Math.round(LU * 0.12))
  const at = [0.3, 0.5, 0.7]
  for (let k = 0; k < NK; k++) {
    kU[k] = Math.round(LU * at[k] - du / 2)
    kV[k] = Math.round(LV / 2 - dv / 2 + (k === 1 ? 0 : (k === 0 ? -1 : 1) * LV * 0.12))
    kDU[k] = du
    kDV[k] = dv
    blockCount++
  }
}

/** The empty field into the background layer and the cells. */
export function drawField() {
  target(bg, cols, rows)
  clip(0, 0, cols, rows)
  if (round) {
    // Round: the table around the field, and a line across each end.
    fill(0, 0, cols, rows, UI_PANEL)
    rect(0, 0, LU, LV, FIELD)
    for (let u = 0; u < LU; u += 2) {
      rect(u, 0, 1, 1, WALL)
      rect(u, LV - 1, 1, 1, WALL)
    }
  } else fill(0, 0, cols, rows, FIELD)
  // The walls along both sides and a dashed line across the middle.
  rect(0, 0, 1, LV, WALL)
  rect(LU - 1, 0, 1, LV, WALL)
  const dash = Math.max(2, (LU / 24) | 0)
  const mid = (LV / 2) | 0
  for (let u = 2; u < LU - 2; u += dash * 2) rect(u, mid, dash, 1, LINE)
  // The pause button, on the middle line by the first wall.
  const ps = PAUSE[2]
  rect(PAUSE[0], PAUSE[1], ps, ps, LINE)
  rect(PAUSE[0] + 1, PAUSE[1] + 1, ps - 2, ps - 2, FIELD)
  const bar = Math.max(1, (ps / 6) | 0)
  const c = (ps / 2) | 0
  if (across) {
    rect(PAUSE[0] + 2, PAUSE[1] + c - bar - 1, ps - 4, bar, PAUSE_ICON)
    rect(PAUSE[0] + 2, PAUSE[1] + c + 1, ps - 4, bar, PAUSE_ICON)
  } else {
    rect(PAUSE[0] + c - bar - 1, PAUSE[1] + 2, bar, ps - 4, PAUSE_ICON)
    rect(PAUSE[0] + c + 1, PAUSE[1] + 2, bar, ps - 4, PAUSE_ICON)
  }
  drawScores()
  target(cells, cols, rows)
  clip(0, 0, cols, rows)
  cells.set(bg)
  padDrawn.fill(-99)
  pAt.fill(-1)
  trail.fill(-99)
}

/** Both scores, big, into the background: each player's in their half,
 *  the top player's upside down on a tall screen. */
function drawScores() {
  let s = Math.max(2, Math.min(7, Math.round(Math.min(LU, LV) / 22)))
  if (round) {
    // Round: in the arc above the field (beside it, the ends up and down), as big as fits the circle there.
    const r = Math.min(cols, rows) / 2 - 2
    for (; s > 1; s--) {
      const far = across ? rows / 2 - (Y0 - 3 - 5 * s) : cols / 2 - (X0 + LU + 3 + textWidth('15', s))
      const half = Math.sqrt(Math.max(0, r * r - far * far))
      if (half >= (across ? 3 + textWidth('15', s) : (LV * 0.08 | 0) + 5 * s + 3)) break
    }
  }
  for (let p = 0; p < 2; p++) {
    const str = String(score[p])
    const w = textWidth(str, s)
    const h = 5 * s
    const gap = Math.max(3, (LV * 0.08) | 0)
    if (round) {
      if (across) {
        const x = X0 + (p === 0 ? (LV >> 1) - 3 - w : (LV >> 1) + 3 + 1)
        fill(X0 + (p === 0 ? 0 : LV >> 1), Y0 - 3 - h - 1, LV >> 1, h + 2, UI_PANEL)
        text(str, x, Y0 - 3 - h, s, p === 0 ? P0_SCORE : P1_SCORE)
      } else {
        const x = X0 + LU + 3
        const y = Y0 + (p === 0 ? (LV >> 1) - gap - h : (LV >> 1) + gap + 1)
        fill(x - 1, y - 1, textWidth('15', s) + 2, h + 2, UI_PANEL)
        text(str, x, y, s, p === 0 ? P0_SCORE : P1_SCORE, false, p === 0)
      }
    } else if (across) {
      // Beside the middle line, near the top.
      const x = p === 0 ? (LV >> 1) - gap - w : (LV >> 1) + gap + 1
      fill(x - 1, 3, w + 2, h + 2, FIELD)
      text(str, x, 4, s, p === 0 ? P0_SCORE : P1_SCORE)
    } else {
      // Above and below the middle line, by the right wall.
      const x = LU - w - Math.max(3, (LU * 0.08) | 0)
      const y = p === 0 ? (LV >> 1) - gap - h : (LV >> 1) + gap + 1
      fill(x - 1, y - 1, w + 2, h + 2, FIELD)
      text(str, x, y, s, p === 0 ? P0_SCORE : P1_SCORE, false, p === 0)
    }
  }
  // The posts over everything, so a score never hides one.
  for (let k = 0; k < blockCount; k++) {
    rect(kU[k], kV[k], kDU[k], kDV[k], BLOCK_EDGE)
    if (kDU[k] > 2 && kDV[k] > 2) rect(kU[k] + 1, kV[k] + 1, kDU[k] - 2, kDV[k] - 2, BLOCK)
  }
}

function serve() {
  rally = 0
  speed = speed0
  for (let b = 0; b < NB; b++) {
    bOn[b] = b === 0 || twoBalls ? 1 : 0
    // From the middle, or beside the middle post when there are posts.
    bU[b] = LU * (blocks ? 0.6 : 0.5) - BS / 2
    bV[b] = LV / 2 - BS / 2
    bWait[b] = b === 0 ? 70 : 190
    const angle = (rfloat() - 0.5) * 1.0
    const dir = (b === 0 ? serveTo : 1 - serveTo) === 0 ? -1 : 1
    bVU[b] = Math.sin(angle) * speed
    bVV[b] = Math.cos(angle) * speed * dir
  }
}

// --- a step ----------------------------------------------------------------------------------

/**
 * One step. `move0` / `move1`: -1, 0, 1 (keys and buttons); `aim0` / `aim1`:
 * where a finger wants a paddle's middle (u), or -1; `ai` 0..2 plays player 0
 * for the computer, -1 for a person.
 */
export function tick(move0: number, move1: number, aim0: number, aim1: number, ai: number) {
  if (flash) flash--
  steer(0, move0, aim0, ai)
  steer(1, move1, aim1, -1)
  for (let b = 0; b < NB; b++) if (bOn[b]) moveBall(b)
  for (let i = 0; i < NP; i++) if (pLife[i]) {
    pLife[i]--
    pU[i] += pVU[i]
    pV[i] += pVV[i]
  }
}

const AI_EVERY = [22, 11, 5]
const AI_SPEED = [0.55, 0.85, 1.25]
const AI_MISS = [0.55, 0.3, 0.12]
let aiTarget = -1
let aiClock = 0

function steer(p: number, move: number, aim: number, ai: number) {
  const fast = Math.max(1, LU / 70)
  if (ai >= 0) {
    if (--aiClock <= 0) {
      aiClock = AI_EVERY[ai]
      aiTarget = predict() + (rfloat() - 0.5) * PL * AI_MISS[ai] * 2
    }
    const want = aiTarget - PL / 2
    const d = want - padU[p]
    const max = AI_SPEED[ai] * fast
    padU[p] += d > max ? max : d < -max ? -max : d
  } else if (aim >= 0) {
    // A finger: the paddle's middle goes where it is, quickly.
    const d = aim - PL / 2 - padU[p]
    const max = 4 * fast
    padU[p] += d > max ? max : d < -max ? -max : d
  } else if (move) padU[p] += move * 1.3 * fast
  if (padU[p] < 1) padU[p] = 1
  if (padU[p] > LU - 1 - PL) padU[p] = LU - 1 - PL
}

/** Where the computer thinks the nearest ball coming its way will cross its paddle's line. */
function predict(): number {
  let best = -1
  let soonest = 1e9
  for (let b = 0; b < NB; b++) {
    if (!bOn[b] || bVV[b] >= 0 || bWait[b] > 0) continue
    const t = (bV[b] - PD - PT) / -bVV[b]
    if (t < soonest) {
      soonest = t
      best = b
    }
  }
  if (best < 0) return LU / 2 // nothing coming: back to the middle
  // Along u, bouncing off the walls on the way.
  let u = bU[best] + BS / 2 + bVU[best] * soonest
  const span = LU - 2
  u = ((u - 1) % (2 * span) + 2 * span) % (2 * span)
  if (u > span) u = 2 * span - u
  return u + 1
}

function moveBall(b: number) {
  if (bWait[b] > 0) {
    bWait[b]--
    return
  }
  // In small steps, so a fast ball never passes through a paddle.
  const n = 1 + ((Math.abs(bVV[b]) + Math.abs(bVU[b])) | 0)
  for (let k = 0; k < n; k++) {
    bU[b] += bVU[b] / n
    bV[b] += bVV[b] / n
    if (bU[b] < 1) {
      bU[b] = 1
      bVU[b] = -bVU[b]
    } else if (bU[b] > LU - 1 - BS) {
      bU[b] = LU - 1 - BS
      bVU[b] = -bVU[b]
    }
    if (paddle(b, 0) || paddle(b, 1)) continue
    for (let q = 0; q < blockCount; q++) block(b, q)
    if (bV[b] < -BS - 2 || bV[b] > LV + 2) {
      point(bV[b] < 0 ? 1 : 0)
      return
    }
  }
}

function paddle(b: number, p: number): boolean {
  const face = p === 0 ? PD + PT : LV - PD - PT
  const coming = p === 0 ? bVV[b] < 0 : bVV[b] > 0
  if (!coming) return false
  const v = bV[b]
  const inV = p === 0 ? v <= face && v + BS > PD : v + BS >= face && v < LV - PD
  if (!inV) return false
  const u = bU[b] + BS / 2
  if (u < padU[p] - 1 || u > padU[p] + PL + 1) return false
  // Returned: off the paddle at an angle from where it hit, a little faster.
  rally++
  speed = Math.min(speed0 * 2.7, speed * speedUp)
  const off = Math.max(-1, Math.min(1, (u - (padU[p] + PL / 2)) / (PL / 2)))
  const angle = off * 1.05
  bVU[b] = Math.sin(angle) * speed
  bVV[b] = Math.cos(angle) * speed * (p === 0 ? 1 : -1)
  bV[b] = p === 0 ? face + 0.01 : face - BS - 0.01
  sparks(bU[b] + BS / 2, p === 0 ? face : face, p === 0 ? 1 : -1)
  return true
}

function block(b: number, q: number) {
  const u = bU[b]
  const v = bV[b]
  if (u + BS <= kU[q] || u >= kU[q] + kDU[q] || v + BS <= kV[q] || v >= kV[q] + kDV[q]) return
  // Out the way it came in: whichever side it is least deep into.
  const inU = Math.min(u + BS - kU[q], kU[q] + kDU[q] - u)
  const inV = Math.min(v + BS - kV[q], kV[q] + kDV[q] - v)
  if (inU < inV) {
    bVU[b] = -bVU[b]
    bU[b] += bVU[b] > 0 ? inU : -inU
  } else {
    bVV[b] = -bVV[b]
    bV[b] += bVV[b] > 0 ? inV : -inV
  }
}

let matchTo = 7

function point(by: number) {
  score[by]++
  flash = 18
  flashBy = by
  serveTo = 1 - by
  for (let b = 0; b < NB; b++) bOn[b] = 0
  target(bg, cols, rows)
  clip(0, 0, cols, rows)
  drawScores()
  target(cells, cols, rows)
  clip(0, 0, cols, rows)
  // The new number into the cells too.
  cells.set(bg)
  padDrawn.fill(-99)
  pAt.fill(-1)
  trail.fill(-99)
  if (score[by] >= matchTo) winner = by
  else serve()
}

export function setMatchTo(n: number) {
  matchTo = n
}

/** Who won the match: 0, 1, or -1 while it goes on. */
export function winnerOf(): number {
  return winner
}

function sparks(u: number, v: number, dir: number) {
  for (let i = 0, n = 6; i < NP && n > 0; i++) {
    if (pLife[i]) continue
    pLife[i] = 8 + rint(8)
    pU[i] = u
    pV[i] = v
    pVU[i] = (rfloat() - 0.5) * 1.6
    pVV[i] = dir * (0.3 + rfloat() * 0.9)
    n--
  }
}

/** Who scored last, and for how much longer the field shows it (a flash). */
export function flashing(): number {
  return flash ? flashBy + 1 : 0
}

// --- drawing ---------------------------------------------------------------------------------

/** Takes away what moved, and draws the paddles, the balls and the sparks where they are now. */
export function draw(step: number) {
  clip(0, 0, cols, rows)
  for (let i = 0; i < NP; i++) {
    if (pAt[i] >= 0) {
      cells[pAt[i]] = bg[pAt[i]]
      pAt[i] = -1
    }
  }
  for (let b = 0; b < NB; b++) {
    for (let k = 0; k < 3; k++) {
      const u = trail[b * 6 + k * 2]
      if (u > -50) back(u, trail[b * 6 + k * 2 + 1], BS, BS)
    }
  }
  for (let p = 0; p < 2; p++) {
    // Drawn every frame: a ball that crossed a paddle took cells of it away.
    const u = padU[p] | 0
    const v = p === 0 ? PD : LV - PD - PT
    if (padDrawn[p] > -50 && padDrawn[p] !== u) back(padDrawn[p], v, PL, PT)
    rect(u, v, PL, PT, p === 0 ? P0 : P1)
    // A darker back edge, so it reads as a bat.
    rect(u, p === 0 ? v : v + PT - 1, PL, 1, p === 0 ? P0_D : P1_D)
    padDrawn[p] = u
  }
  for (let b = 0; b < NB; b++) {
    const at = b * 6
    // Shift the trail: the oldest goes, the ball's last place is the newest ghost.
    trail[at + 4] = trail[at + 2]
    trail[at + 5] = trail[at + 3]
    trail[at + 2] = trail[at]
    trail[at + 3] = trail[at + 1]
    if (!bOn[b] || (bWait[b] > 0 && (step >> 3) & 1)) {
      trail[at] = -99
      continue
    }
    trail[at] = bU[b] | 0
    trail[at + 1] = bV[b] | 0
    if (trail[at + 4] > -50) rect(trail[at + 4], trail[at + 5], BS, BS, GHOST2)
    if (trail[at + 2] > -50) rect(trail[at + 2], trail[at + 3], BS, BS, GHOST)
    rect(trail[at], trail[at + 1], BS, BS, BALL)
    if (BS > 2) rect(trail[at] + 1, trail[at + 1] + 1, BS - 2, BS - 2, BALL_GLOW)
  }
  for (let i = 0; i < NP; i++) {
    if (!pLife[i]) continue
    const u = pU[i] | 0
    const v = pV[i] | 0
    if (u < 0 || v < 0 || u >= LU || v >= LV) continue
    const at = across ? (Y0 + u) * cols + X0 + v : (Y0 + v) * cols + X0 + u
    cells[at] = SPARK
    pAt[i] = at
  }
}

/** Where the computer's or a person's paddles are, for a fresh field. */
export function centrePaddles() {
  padU[0] = padU[1] = (LU - PL) / 2
}

/** The match's place, to come back to after the interpreter was dropped. */
export function snapshot() {
  return { s0: score[0], s1: score[1] }
}

export function resume(snap: any, twist: string, faster: number) {
  newMatch(twist, faster)
  score[0] = snap.s0 | 0
  score[1] = snap.s1 | 0
  drawField()
}

sources.gfx.ts:
// Drawing into the cells of the 8-bit palette mode: a byte a cell, an index
// into the game's palette. Everything here draws into one target, set with
// target() when the cells are made; every shape is clipped to it. Rows are
// filled with Uint8Array.fill, which is one native memset a run: far cheaper
// than a loop of cell writes in QuickJS.

let C: Uint8Array = new Uint8Array(1)
let CW = 1 // the grid's width: a row's stride
// The clip box: nothing is drawn outside [X0, X1) x [Y0, Y1).
let X0 = 0
let Y0 = 0
let X1 = 1
let Y1 = 1

/** The cells everything draws into: a grid `w` cells wide and `h` high,
 *  clipped to all of it. */
export function target(cells: Uint8Array, w: number, h: number) {
  C = cells
  CW = w
  X0 = 0
  Y0 = 0
  X1 = w
  Y1 = h
}

/** Draw only inside this rectangle (a play area under a score strip). */
export function clip(x: number, y: number, w: number, h: number) {
  X0 = x
  Y0 = y
  X1 = x + w
  Y1 = y + h
}

/** A filled rectangle. */
export function fill(x: number, y: number, w: number, h: number, v: number) {
  let x0 = x | 0
  let x1 = (x + w) | 0
  let y0 = y | 0
  let y1 = (y + h) | 0
  if (x0 < X0) x0 = X0
  if (y0 < Y0) y0 = Y0
  if (x1 > X1) x1 = X1
  if (y1 > Y1) y1 = Y1
  if (x0 >= x1) return
  for (let r = y0; r < y1; r++) C.fill(v, r * CW + x0, r * CW + x1)
}

/** One cell. */
export function put(x: number, y: number, v: number) {
  if (x >= X0 && y >= Y0 && x < X1 && y < Y1) C[(y | 0) * CW + (x | 0)] = v
}

/** A button-ish box: a face with a border and its corners cut off (left as
 *  `under`, what the box sits on). */
export function box(x: number, y: number, w: number, h: number, face: number, border: number, under: number) {
  fill(x, y, w, h, border)
  fill(x + 1, y + 1, w - 2, h - 2, face)
  put(x, y, under)
  put(x + w - 1, y, under)
  put(x, y + h - 1, under)
  put(x + w - 1, y + h - 1, under)
}

/** Copies a rectangle from `layer` (cells of the same grid) back into the
 *  target: what a moving thing covered, put back. */
export function restore(layer: Uint8Array, x: number, y: number, w: number, h: number) {
  let x0 = x | 0
  let x1 = (x + w) | 0
  let y0 = y | 0
  let y1 = (y + h) | 0
  if (x0 < X0) x0 = X0
  if (y0 < Y0) y0 = Y0
  if (x1 > X1) x1 = X1
  if (y1 > Y1) y1 = Y1
  for (let r = y0; r < y1; r++) {
    const row = r * CW
    for (let i = row + x0; i < row + x1; i++) C[i] = layer[i]
  }
}

// --- sprites ---------------------------------------------------------------

/** A sprite: `w` x `h` palette indexes, 255 where it is see-through. */
export type Sprite = { w: number; h: number; d: Uint8Array }

/**
 * A sprite from a compact string: rows split by `|`, a character a cell, `.`
 * see-through, and every other character the palette index at its place in
 * `values` for its place in `keys` ("ab", [12, 13]: a is 12, b is 13).
 */
export function sprite(text: string, keys: string, values: number[]): Sprite {
  const lines = text.split('|')
  const h = lines.length
  let w = 0
  for (const line of lines) if (line.length > w) w = line.length
  const d = new Uint8Array(w * h).fill(255)
  for (let y = 0; y < h; y++) {
    const line = lines[y]
    for (let x = 0; x < line.length; x++) {
      const k = keys.indexOf(line[x])
      if (k >= 0) d[y * w + x] = values[k]
    }
  }
  return { w, h, d }
}

/** Draws a sprite with its top left at (x, y). `tint` (when not 255) paints
 *  every solid cell that one index: a flash when something is hit. */
export function blit(s: Sprite, x: number, y: number, tint = 255) {
  const sw = s.w
  const d = s.d
  x = x | 0
  y = y | 0
  let sx0 = 0
  let sy0 = 0
  let sx1 = sw
  let sy1 = s.h
  if (x < X0) sx0 = X0 - x
  if (y < Y0) sy0 = Y0 - y
  if (x + sx1 > X1) sx1 = X1 - x
  if (y + sy1 > Y1) sy1 = Y1 - y
  for (let sy = sy0; sy < sy1; sy++) {
    const src = sy * sw
    const dst = (y + sy) * CW + x
    for (let sx = sx0; sx < sx1; sx++) {
      const v = d[src + sx]
      if (v !== 255) C[dst + sx] = tint === 255 ? v : tint
    }
  }
}

/** Puts back what a sprite at (x, y) covered: only its solid cells, from `layer`. */
export function unblit(s: Sprite, x: number, y: number, layer: Uint8Array) {
  const sw = s.w
  const d = s.d
  x = x | 0
  y = y | 0
  let sx0 = 0
  let sy0 = 0
  let sx1 = sw
  let sy1 = s.h
  if (x < X0) sx0 = X0 - x
  if (y < Y0) sy0 = Y0 - y
  if (x + sx1 > X1) sx1 = X1 - x
  if (y + sy1 > Y1) sy1 = Y1 - y
  for (let sy = sy0; sy < sy1; sy++) {
    const src = sy * sw
    const dst = (y + sy) * CW + x
    for (let sx = sx0; sx < sx1; sx++) {
      if (d[src + sx] !== 255) C[dst + sx] = layer[dst + sx]
    }
  }
}

// --- text ------------------------------------------------------------------

// A 3x5 font, 15 bits a glyph, the top row first and each row's left dot its
// high bit. Letters, digits and a little punctuation; `@` is a heart.
const GLYPHS: Record<string, number> = {
  A: 0x2bed, B: 0x6bae, C: 0x3923, D: 0x6b6e, E: 0x79a7, F: 0x79a4, G: 0x396b, H: 0x5bed, I: 0x7497,
  J: 0x126a, K: 0x5bad, L: 0x4927, M: 0x5fed, N: 0x6b6d, O: 0x2b6a, P: 0x6ba4, Q: 0x2b73, R: 0x6bad,
  S: 0x388e, T: 0x7492, U: 0x5b6f, V: 0x5b6a, W: 0x5bfd, X: 0x5aad, Y: 0x5a92, Z: 0x72a7,
  0: 0x7b6f, 1: 0x2c97, 2: 0x73e7, 3: 0x73cf, 4: 0x5bc9, 5: 0x79cf, 6: 0x79ef, 7: 0x7249, 8: 0x7bef, 9: 0x7bcf,
  '-': 0x01c0, '+': 0x05d0, '<': 0x1511, '>': 0x4454, '.': 0x0002, ':': 0x0410, '/': 0x12a4, ' ': 0,
  '!': 0x2482, '?': 0x7282, "'": 0x2400, ',': 0x0014, '%': 0x52a5, '#': 0x5f7d, '*': 0x0aa8, '=': 0x0e38,
  '(': 0x2922, ')': 0x224a, '@': 0x5fd0, '_': 0x0007,
}

/** A character's 15 dots (0 for one the font lacks). */
export function glyphBits(ch: string): number {
  return GLYPHS[ch] ?? GLYPHS[ch.toUpperCase()] ?? 0
}

/** Cells a line of text takes at `scale`: 4 dots a letter, less the last gap. */
export function textWidth(text: string, scale: number): number {
  return text.length ? (text.length * 4 - 1) * scale : 0
}

/**
 * Text with its top left at (x, y), `scale` cells a dot. With `ramp` each row
 * of dots is one index further from `v` (v, v+1, ... v+4: a gradient down the
 * letters); with `upside` it is turned 180 degrees, for the player across the
 * table.
 */
export function text(s: string, x: number, y: number, scale: number, v: number, ramp = false, upside = false) {
  const n = s.length
  for (let g = 0; g < n; g++) {
    const ch = s[upside ? n - 1 - g : g]
    const bits = glyphBits(ch)
    if (!bits) continue
    const left = x + g * 4 * scale
    for (let i = 0; i < 15; i++) {
      const bit = upside ? i : 14 - i
      if (!(bits & (1 << bit))) continue
      const dotRow = (i / 3) | 0
      fill(left + (i % 3) * scale, y + dotRow * scale, scale, scale, ramp ? v + (upside ? 4 - dotRow : dotRow) : v)
    }
  }
}

/** Text centred on column `cx`. */
export function textCenter(s: string, cx: number, y: number, scale: number, v: number, ramp = false) {
  text(s, cx - ((textWidth(s, scale) / 2) | 0), y, scale, v, ramp)
}

/** A headline: gradient letters (`v` .. `v`+4) over a drop shadow `shadow`. */
export function title(s: string, cx: number, y: number, scale: number, v: number, shadow: number) {
  const x = cx - ((textWidth(s, scale) / 2) | 0)
  const off = scale > 1 ? (scale / 2) | 0 : 1
  text(s, x + off, y + off, scale, shadow)
  text(s, x, y, scale, v, true)
}

// The digits' glyphs, for numbers drawn every frame without making a string.
const DIGITS = new Int32Array(10)
for (let d = 0; d < 10; d++) DIGITS[d] = GLYPHS[String(d)]

/** A whole number at (x, y), at least `width` digits (zeros in front), with
 *  no string made: a speed or a clock drawn every frame. Answers its width. */
export function number(n: number, x: number, y: number, scale: number, v: number, width = 1): number {
  n = n < 0 ? 0 : n | 0
  let count = 1
  for (let k = n; k >= 10; k = (k / 10) | 0) count++
  if (count < width) count = width
  let at = x + (count - 1) * 4 * scale
  for (let i = 0; i < count; i++) {
    const bits = DIGITS[n % 10]
    for (let b = 0; b < 15; b++) {
      if (bits & (1 << (14 - b))) fill(at + (b % 3) * scale, y + ((b / 3) | 0) * scale, scale, scale, v)
    }
    n = (n / 10) | 0
    at -= 4 * scale
  }
  return count * 4 * scale - scale
}

sources.input.ts:
// Input for the games: touch (each finger by its pointerId, so one can hold
// left while another fires), GPIO buttons (down and up the moment they
// happen) and a keyboard, all folded into one set of action bits. What is
// held is held(); a press that came and went between two frames still counts
// once through take(), so a quick tap of a GPIO key is never lost.

export const LEFT = 1
export const RIGHT = 2
export const UP = 4
export const DOWN = 8
export const A = 16
export const B = 32
export const START = 64 // pause / resume / start
export const TAP = 128 // a finger or a click on the play area (not a control)

const ACTIONS: Record<string, number> = {
  left: LEFT, right: RIGHT, up: UP, down: DOWN, a: A, fire: A, b: B, bomb: B, brake: B,
  start: START, pause: START, gas: A, jump: A, button: A,
}

const MAX = 32 // pointer ids are folded into this many slots
const ptrBits = new Uint8Array(MAX)
const ptrDrag = new Uint8Array(MAX)
/** Which pointers are down on the play area (not on a control), by id. */
export const drags = ptrDrag
/** Where each dragging pointer is now and where it went down, in scene pixels. */
export const ptrX = new Int16Array(MAX)
export const ptrY = new Int16Array(MAX)
export const ptrStartX = new Int16Array(MAX)
export const ptrStartY = new Int16Array(MAX)
const pinBits = new Uint8Array(64)
let keyBits = 0
let gpioBits = 0
let latched = 0
let gpioSeen = false
let labels: Record<string, number> = {}
let hitTest: (x: number, y: number) => number = () => 0
// What was used last: 'touch', 'key' or 'gpio'.
let lastKind = ''
let tapX = 0
let tapY = 0

/** How a pointer at (x, y) scene pixels hits the on-screen controls: their
 *  action bits, or 0 for the play area (a drag there). */
export function setHitTest(fn: (x: number, y: number) => number) {
  hitTest = fn
}

/** The "Buttons" setting: `LEFT=left, RIGHT=right, KEY1=a`. Labels (and
 *  roles) are matched without case; a key it does not name is A. */
export function setButtons(spec: string) {
  labels = {}
  for (const part of String(spec || '').split(',')) {
    const eq = part.indexOf('=')
    if (eq < 0) continue
    const name = part.slice(0, eq).trim().toLowerCase()
    const action = ACTIONS[part.slice(eq + 1).trim().toLowerCase()]
    if (name && action) labels[name] = action
  }
}

function gpioAction(payload: any): number {
  const label = String(payload.label || '').toLowerCase()
  const role = String(payload.role || '').toLowerCase()
  return labels[label] || labels[role] || ACTIONS[label] || A
}

/** The default keys: arrows and WASD, Space / Z / J for A, X / K / C for B,
 *  Enter, P and Escape to pause. */
export function keyAction(code: string): number {
  switch (code) {
    case 'ArrowLeft': case 'KeyA': return LEFT
    case 'ArrowRight': case 'KeyD': return RIGHT
    case 'ArrowUp': case 'KeyW': return UP
    case 'ArrowDown': case 'KeyS': return DOWN
    case 'Space': case 'KeyZ': case 'KeyJ': return A
    case 'KeyX': case 'KeyK': case 'KeyC': return B
    case 'Enter': case 'NumpadEnter': case 'KeyP': case 'Escape': return START
  }
  return 0
}

function recount() {
  let g = 0
  for (let i = 0; i < 64; i++) g |= pinBits[i]
  gpioBits = g
}

/**
 * One input event. Answers the action bits it pressed (0 when it pressed
 * nothing, -1 when it was not input at all), so a game can react at once.
 * `keys` maps a key code to bits (keyAction by default).
 */
export function handle(event: string, p: any, keys: (code: string) => number = keyAction): number {
  if (event === 'pointerDown' || event === 'pointerMove') {
    const id = (p.pointerId | 0) & (MAX - 1)
    const x = p.x | 0
    const y = p.y | 0
    if (event === 'pointerMove' && !ptrBits[id] && !ptrDrag[id]) return 0 // a mouse passing over
    lastKind = 'touch'
    if (event === 'pointerDown') {
      const bits = hitTest(x, y)
      ptrBits[id] = bits
      ptrDrag[id] = bits ? 0 : 1
      ptrX[id] = ptrStartX[id] = x
      ptrY[id] = ptrStartY[id] = y
      tapX = x
      tapY = y
      latched |= bits || TAP
      return bits || TAP
    }
    ptrX[id] = x
    ptrY[id] = y
    if (ptrBits[id]) {
      // A thumb sliding from one button to the next presses that one.
      const bits = hitTest(x, y)
      const fresh = bits & ~ptrBits[id]
      ptrBits[id] = bits
      latched |= fresh
      return fresh
    }
    return 0
  }
  if (event === 'pointerUp' || event === 'pointerCancel') {
    const id = (p.pointerId | 0) & (MAX - 1)
    ptrBits[id] = 0
    ptrDrag[id] = 0
    return 0
  }
  if (event === 'keyDown' || event === 'keyUp') {
    const bits = keys(String(p.code || p.key || ''))
    if (!bits) return 0
    lastKind = 'key'
    if (event === 'keyUp') {
      keyBits &= ~bits
      return 0
    }
    if (p.repeat) return 0
    keyBits |= bits
    latched |= bits
    return bits
  }
  if (event === 'gpio') {
    gpioSeen = true
    lastKind = 'gpio'
    const pin = (p.pin | 0) & 63
    if (p.action === 'down') {
      const bits = gpioAction(p)
      pinBits[pin] = bits
      latched |= bits
      recount()
      return bits
    }
    if (p.action === 'up') {
      pinBits[pin] = 0
      recount()
    }
    return 0
  }
  if (event === 'button') {
    // Only where no gpio edges arrive: a press after the release.
    if (gpioSeen || (p.action !== 'press' && p.action !== 'doublePress')) return 0
    lastKind = 'gpio'
    const bits = gpioAction(p)
    latched |= bits
    return bits
  }
  return -1
}

/** Everything held now. */
export function held(): number {
  let bits = keyBits | gpioBits
  for (let i = 0; i < MAX; i++) bits |= ptrBits[i]
  return bits
}

/** Counts as a press of `bits` (a swipe in from an edge that means pause). */
export function press(bits: number) {
  latched |= bits
}

/** The presses since the last call. */
export function take(): number {
  const bits = latched
  latched = 0
  return bits
}

/** The id of a finger dragging on the play area, or -1. */
export function dragging(): number {
  for (let i = 0; i < MAX; i++) if (ptrDrag[i]) return i
  return -1
}

/** Where the last finger or click went down, in scene pixels. */
export function lastTapX(): number {
  return tapX
}
export function lastTapY(): number {
  return tapY
}

/** Every finger lets go (a pause, the scene closing). */
export function releaseAll() {
  ptrBits.fill(0)
  ptrDrag.fill(0)
  pinBits.fill(0)
  keyBits = 0
  gpioBits = 0
  latched = 0
}

/** Whether a keyboard was the last thing used. */
export function usingKeyboard(): boolean {
  return lastKind === 'key'
}

sources.controls.ts:
// The on-screen controls: a D-pad (left/right, or a cross) and up to two
// action buttons, drawn into the cells, with a pause button. On a wide screen
// they sit in panels at both sides (thumbs on a held tablet); on a square or
// tall one in a bar along the bottom. Buttons are at least ~60 px on the
// glass and ~24 px from the screen's edges, where a swipe belongs to the
// frame. The palette indexes they draw with are the kit's UI slots (ui.ts).
import { box, fill, text, textCenter, textWidth } from './gfx'
import { A, B, DOWN, LEFT, RIGHT, START, UP } from './input'
import { UI_BORDER, UI_EDGE, UI_FACE, UI_ICON, UI_ICON_LIT, UI_LIT, UI_PANEL } from './ui'

const ICON_LEFT = 1
const ICON_RIGHT = 2
const ICON_UP = 3
const ICON_DOWN = 4
const ICON_A = 5
const ICON_B = 6
const ICON_PAUSE = 7

export type Layout = {
  /** The play area, in cells. */
  x: number
  y: number
  w: number
  h: number
  wide: boolean
  /** Buttons: 5 numbers each (bits, x, y, w, h) and an icon. */
  n: number
  b: Int16Array
  icon: Uint8Array
  /** Panels behind the buttons: x, y, w, h each. */
  np: number
  panels: Int16Array
  /** The D-pad's box, which picks a direction by where in it a finger is. */
  dx: number
  dy: number
  dw: number
  dh: number
  dpad: number
  gap: number
  px: number
  labelA: string
  labelB: string
  /** A round panel's: the game's name in the arc above the play area, at (nameX, nameY). */
  name?: string
  nameX?: number
  nameY?: number
}

/**
 * Where everything goes on a `cols` x `rows` grid of `px`-pixel cells.
 * `dpad` 0 (none), 2 (left and right) or 4 (a cross); `actions` 0, 1 (A) or
 * 2 (A and B); `show` false leaves the whole screen to the game. `sides`
 * false keeps the bar along the bottom on a wide screen too (a wide view).
 * A small screen (a watch, a 2.8" panel) gets what fits: side panels that
 * would leave the play area too narrow become the bar, buttons shrink to
 * 40 px and the edges to 8 px, a cross that does not fit across becomes
 * left and right (the keys and a drag still go up and down; `L.dpad` says
 * which), and a bar over a third of the height has A and B side by side.
 */
export function layout(cols: number, rows: number, px: number, dpad: number, actions: number, show: boolean,
    labelA = 'A', labelB = 'B', sides = true): Layout {
  const L: Layout = {
    x: 0, y: 0, w: cols, h: rows, wide: sides && cols >= rows * 1.25, n: 0, b: new Int16Array(40), icon: new Uint8Array(8),
    np: 0, panels: new Int16Array(8), dx: 0, dy: 0, dw: 0, dh: 0, dpad, gap: 1, px, labelA, labelB,
  }
  if (!show) return L
  const fullBs = Math.max(8, Math.ceil(60 / px)) // a button, in cells
  const leastBs = Math.min(fullBs, Math.max(7, Math.ceil(40 / px)))
  const fullEdge = Math.max(2, Math.ceil(24 / px)) // kept free along the screen's edges
  const leastEdge = Math.min(fullEdge, Math.max(1, Math.ceil(8 / px)))
  let want = fullBs
  let edge = fullEdge
  let bs = want
  let gap = 1
  let padW = 0
  let padH = 0
  let actW = 0
  let actH = 0
  let ps = 0
  let flat = false // A and B side by side
  const measure = () => {
    bs = dpad === 4 ? Math.max(7, Math.min(want, Math.floor((rows - 2 * edge) / 3.6))) : want
    gap = Math.max(1, Math.round(bs / 6))
    ps = Math.max(6, Math.round(bs * 0.65)) // the pause button
    padW = dpad === 4 ? 3 * bs : dpad === 2 ? 2 * bs + gap : 0
    padH = dpad === 4 ? 3 * bs : dpad === 2 ? bs : 0
    actW = actions === 2 ? 2 * bs + gap : actions === 1 ? bs : 0
    flat = !L.wide && actions === 2 && bs + (bs >> 1) + edge + 2 * gap > rows / 3
    actH = actions === 2 && !flat ? bs + (bs >> 1) : actions >= 1 ? bs : 0
  }
  for (;;) {
    measure()
    if (L.wide) {
      const side = Math.max(padW, actW, ps) + edge + 2 * gap
      if (cols - 2 * side >= rows * 0.75) break
      L.wide = false // the bar instead
      continue
    }
    // The pause button in the middle of the bar, the pad and the actions either side of it.
    if (2 * (edge + Math.max(padW, actW) + gap) + ps <= cols) break
    if (want > leastBs) want--
    else if (edge > leastEdge) edge--
    else if (dpad === 4) {
      dpad = 2
      want = fullBs
      edge = fullEdge
    } else break
  }
  L.gap = gap
  L.dpad = dpad
  const add = (bits: number, x: number, y: number, w: number, h: number, icon: number) => {
    const at = L.n * 5
    L.b[at] = bits
    L.b[at + 1] = x
    L.b[at + 2] = y
    L.b[at + 3] = w
    L.b[at + 4] = h
    L.icon[L.n] = icon
    L.n++
  }
  const panel = (x: number, y: number, w: number, h: number) => {
    L.panels.set([x, y, w, h], L.np * 4)
    L.np++
  }
  let padX = 0
  let padY = 0
  let actX = 0
  let actY = 0
  if (L.wide) {
    const side = Math.max(padW, actW, ps) + edge + 2 * gap
    L.x = side
    L.w = cols - 2 * side
    panel(0, 0, side, rows)
    panel(cols - side, 0, side, rows)
    // The thumbs' places: a little below the middle.
    padX = edge
    padY = Math.min(rows - edge - padH, Math.round(rows * 0.58 - padH / 2))
    actX = cols - edge - actW
    actY = Math.min(rows - edge - actH, Math.round(rows * 0.58 - actH / 2))
    add(START, cols - edge - ps, edge, ps, ps, ICON_PAUSE)
  } else {
    const content = Math.max(padH, actH, ps)
    const bar = content + edge + 2 * gap
    L.h = rows - bar
    panel(0, rows - bar, cols, bar)
    padX = edge
    padY = rows - edge - gap - content + ((content - padH) >> 1)
    actX = cols - edge - actW
    actY = rows - edge - gap - content + ((content - actH) >> 1)
    add(START, (cols - ps) >> 1, rows - edge - gap - content + ((content - ps) >> 1), ps, ps, ICON_PAUSE)
  }
  if (dpad === 2) {
    add(LEFT, padX, padY, bs, bs, ICON_LEFT)
    add(RIGHT, padX + bs + gap, padY, bs, bs, ICON_RIGHT)
  } else if (dpad === 4) {
    add(UP, padX + bs, padY, bs, bs, ICON_UP)
    add(LEFT, padX, padY + bs, bs, bs, ICON_LEFT)
    add(RIGHT, padX + 2 * bs, padY + bs, bs, bs, ICON_RIGHT)
    add(DOWN, padX + bs, padY + 2 * bs, bs, bs, ICON_DOWN)
  }
  L.dx = padX
  L.dy = padY
  L.dw = padW
  L.dh = padH
  if (actions === 2) {
    // B up and to the left, A down and to the right, as on a game pad (or level, on a low bar).
    add(B, actX, actY, bs, bs, ICON_B)
    add(A, actX + bs + gap, actY + (flat ? 0 : bs >> 1), bs, bs, ICON_A)
  } else if (actions === 1) {
    add(A, actX, actY, bs, bs, ICON_A)
  }
  return L
}

/**
 * The same for a round panel (context.round), where only the circle inside the
 * square shows: the buttons follow the rim along the bottom (the D-pad on the
 * left, the actions on the right, the pause button in the middle), and the
 * play area is the biggest rectangle inside the circle that they leave
 * free (`square` asks for one about as tall as wide, `wide` for one no
 * taller than three quarters of its width, a wide view). `name` goes in the
 * arc above it. The buttons are 56 px, less on a small glass (13 % of it,
 * 44 px at least).
 */
export function roundLayout(cols: number, rows: number, px: number, dpad: number, actions: number, show: boolean,
    labelA = 'A', labelB = 'B', square = false, name = '', wide = false): Layout {
  const L = layout(cols, rows, px, 0, 0, false, labelA, labelB, false)
  L.dpad = show ? dpad : 0
  const cx = cols / 2
  const cy = rows / 2
  const r = Math.min(cols, rows) / 2 - Math.ceil(12 / px) // kept in from the rim
  const bs = Math.max(8, Math.ceil(Math.max(44, Math.min(56, Math.min(cols, rows) * px * 0.13)) / px))
  const gap = Math.max(1, Math.round(bs / 6))
  const ps = Math.max(6, Math.round(bs * 0.65))
  L.gap = gap
  const add = (bits: number, x: number, y: number, w: number, h: number, icon: number) => {
    const at = L.n * 5
    L.b[at] = bits
    L.b[at + 1] = Math.round(x)
    L.b[at + 2] = Math.round(y)
    L.b[at + 3] = w
    L.b[at + 4] = h
    L.icon[L.n] = icon
    L.n++
  }
  // Where on the rim a button of `size` sits, `angle` from straight down (to the right is positive).
  const spot = (angle: number, size: number) => {
    const at = r - size * 0.72
    return { x: cx + Math.sin(angle) * at - size / 2, y: cy + Math.cos(angle) * at - size / 2 }
  }
  // The next angle out from `from` (a button of `was` cells) where a button of `size` no longer touches it.
  const next = (from: number, was: number, size: number, dir: number) => {
    const a = spot(from, was)
    let angle = from
    for (let i = 0; i < 400; i++) {
      angle += dir * 0.01
      const b = spot(angle, size)
      const dx = Math.abs(b.x + size / 2 - (a.x + was / 2))
      const dy = Math.abs(b.y + size / 2 - (a.y + was / 2))
      if (Math.max(dx, dy) >= (size + was) / 2 + gap) break
    }
    return angle
  }
  if (show) {
    const pause = spot(0, ps)
    add(START, pause.x, pause.y, ps, ps, ICON_PAUSE)
    if (dpad === 2) {
      const right = next(0, ps, bs, -1)
      const left = next(right, bs, bs, -1)
      const a = spot(left, bs)
      const b = spot(right, bs)
      add(LEFT, a.x, a.y, bs, bs, ICON_LEFT)
      add(RIGHT, b.x, b.y, bs, bs, ICON_RIGHT)
      L.dx = Math.round(a.x)
      L.dy = Math.round(Math.min(a.y, b.y))
      L.dw = Math.round(b.x) + bs - L.dx
      L.dh = Math.round(Math.max(a.y, b.y)) + bs - L.dy
    } else if (dpad === 4) {
      // A cross, smaller, on the rim down and to the left.
      const c = Math.max(Math.ceil(44 / px), Math.round(bs * 0.8))
      const at = spot(-0.62, c * 3)
      add(UP, at.x + c, at.y, c, c, ICON_UP)
      add(LEFT, at.x, at.y + c, c, c, ICON_LEFT)
      add(RIGHT, at.x + 2 * c, at.y + c, c, c, ICON_RIGHT)
      add(DOWN, at.x + c, at.y + 2 * c, c, c, ICON_DOWN)
      L.dx = Math.round(at.x)
      L.dy = Math.round(at.y)
      L.dw = 3 * c
      L.dh = 3 * c
    }
    if (actions >= 1) {
      // B nearer the middle and up the rim, A further out, as a thumb rolls.
      const first = next(0, ps, bs, 1)
      const p = spot(actions === 2 ? next(first, bs, bs, 1) : first, bs)
      if (actions === 2) {
        const q = spot(first, bs)
        add(B, q.x, q.y, bs, bs, ICON_B)
      }
      add(A, p.x, p.y, bs, bs, ICON_A)
    }
  }
  // The play area: corners inside the circle, the biggest that no button
  // overlaps. One up the rim beside it leaves it narrower, not shorter: it
  // reaches `a` cells above the middle and `b` below, and is as wide as the
  // circle and the buttons at those heights let it be.
  let best = -1
  for (let a = 4; a < r; a++) {
    for (let b = 4; b <= a; b++) {
      let hw = Math.floor(Math.sqrt(r * r - a * a))
      const top = cy - a
      const bottom = cy + b
      for (let i = 0; i < L.n && hw >= 4; i++) {
        const at = i * 5
        const bx = L.b[at + 1]
        const by = L.b[at + 2]
        const bw = L.b[at + 3]
        if (by + L.b[at + 4] + gap <= top || by - gap >= bottom) continue
        const near = bx >= cx ? bx - gap - cx : bx + bw + gap <= cx ? cx - bx - bw - gap : 0
        if (near < hw) hw = Math.floor(near)
      }
      const h = a + b
      if (hw < 4 || (wide && h * 4 > hw * 6)) continue
      const score = square ? Math.min(2 * hw, h) : hw * h
      if (score > best) {
        best = score
        L.x = Math.round(cx - hw)
        L.w = 2 * hw
        L.y = Math.round(cy - a)
        L.h = h
      }
    }
  }
  if (name) {
    // The name in the arc above, where it fits.
    const y = Math.round((cy - r + L.y) / 2) - 2
    const half = Math.sqrt(Math.max(0, r * r - (cy - y) * (cy - y)))
    if (y > cy - r && textWidth(name, 1) < 2 * half - 2) {
      L.name = name
      L.nameX = Math.round(cx)
      L.nameY = y
    }
  }
  return L
}

/** What a pointer at (x, y) scene pixels presses: action bits, or 0 for the
 *  play area and the bare panels. */
export function hit(L: Layout, x: number, y: number): number {
  const cx = x / L.px
  const cy = y / L.px
  const g = L.gap
  // The D-pad as one pad: a direction by where on it the thumb is, so a
  // thumb rolling across it never falls between two buttons.
  if (L.dpad && cx >= L.dx - g && cx < L.dx + L.dw + g && cy >= L.dy - g && cy < L.dy + L.dh + g) {
    if (L.dpad === 2) return cx < L.dx + L.dw / 2 ? LEFT : RIGHT
    const mx = cx - (L.dx + L.dw / 2)
    const my = cy - (L.dy + L.dh / 2)
    const dead = L.dw / 6
    let bits = 0
    if (mx < -dead) bits |= LEFT
    if (mx > dead) bits |= RIGHT
    if (my < -dead) bits |= UP
    if (my > dead) bits |= DOWN
    return bits
  }
  for (let i = 0; i < L.n; i++) {
    const at = i * 5
    const bits = L.b[at]
    if (bits & (LEFT | RIGHT | UP | DOWN)) continue
    if (cx >= L.b[at + 1] - g && cy >= L.b[at + 2] - g && cx < L.b[at + 1] + L.b[at + 3] + g &&
        cy < L.b[at + 2] + L.b[at + 4] + g) return bits
  }
  return 0
}

/** Panels and every button. */
export function drawControls(L: Layout, held: number) {
  for (let i = 0; i < L.np; i++) {
    const at = i * 4
    const x = L.panels[at]
    const y = L.panels[at + 1]
    const w = L.panels[at + 2]
    const h = L.panels[at + 3]
    fill(x, y, w, h, UI_PANEL)
    // A line along the side that meets the play area.
    if (L.wide) fill(x === 0 ? x + w - 1 : x, y, 1, h, UI_EDGE)
    else fill(x, y, w, 1, UI_EDGE)
  }
  if (L.name) textCenter(L.name, L.nameX!, L.nameY!, 1, UI_BORDER)
  for (let i = 0; i < L.n; i++) drawButton(L, i, (held & L.b[i * 5]) !== 0)
}

/** Draws again only the buttons whose state changed between `was` and `now`. */
export function updateControls(L: Layout, was: number, now: number) {
  const changed = was ^ now
  if (!changed) return
  for (let i = 0; i < L.n; i++) if (changed & L.b[i * 5]) drawButton(L, i, (now & L.b[i * 5]) !== 0)
}

function drawButton(L: Layout, i: number, lit: boolean) {
  const at = i * 5
  const x = L.b[at + 1]
  const y = L.b[at + 2]
  const w = L.b[at + 3]
  const h = L.b[at + 4]
  box(x, y, w, h, lit ? UI_LIT : UI_FACE, UI_BORDER, UI_PANEL)
  const ink = lit ? UI_ICON_LIT : UI_ICON
  const cx = x + (w >> 1)
  const cy = y + (h >> 1) + (lit ? 1 : 0)
  const icon = L.icon[i]
  const r = Math.max(2, Math.round(w * 0.22))
  if (icon <= ICON_DOWN) arrow(icon, cx, cy, r, ink)
  else if (icon === ICON_PAUSE) {
    const bw = Math.max(1, Math.round(w / 7))
    fill(cx - bw - Math.max(1, bw >> 1), cy - r, bw, 2 * r, ink)
    fill(cx + Math.max(1, bw >> 1), cy - r, bw, 2 * r, ink)
  } else {
    const label = icon === ICON_A ? L.labelA : L.labelB
    // Letters about half the button's height, as wide as fit.
    let scale = Math.max(1, Math.floor((h * 0.5) / 5 + 0.5))
    while (scale > 1 && textWidth(label, scale) > w - 4) scale--
    text(label, cx - ((textWidth(label, scale) / 2) | 0), cy - ((5 * scale) >> 1), scale, ink)
  }
}

/** A filled triangle pointing `dir`, `r` cells from its tip to its base,
 *  centred on (cx, cy). */
function arrow(dir: number, cx: number, cy: number, r: number, v: number) {
  const half = (r + 1) >> 1
  for (let i = 0; i <= r; i++) {
    // i: how far from the tip; the span widens by one each side per step.
    if (dir === ICON_LEFT) fill(cx - half + i, cy - i, 1, 2 * i + 1, v)
    else if (dir === ICON_RIGHT) fill(cx + half - i, cy - i, 1, 2 * i + 1, v)
    else if (dir === ICON_UP) fill(cx - i, cy - half + i, 2 * i + 1, 1, v)
    else fill(cx - i, cy + half - i, 2 * i + 1, 1, v)
  }
}

